package com.pos.cosmos.local.entities

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room entities mirroring the 17 tables synced by the desktop CosmosPOS app.
 * Column sets are intentionally lean for phase 1 — extend them as offline screens
 * (cash bill, image bill, credit bill, purchasing) need more fields.
 *
 * `serverId` is the backend primary key. Local autogenerated `id` lets us insert
 * rows that haven't been pushed yet (e.g. offline-created bills).
 */

@Entity(tableName = "companies")
data class CompanyEntity(
    @PrimaryKey val companyCode: Int,
    val name: String? = null,
    val address: String? = null,
    val telephone: String? = null,
    val email: String? = null,
    val active: String? = "Y"
)

@Entity(tableName = "categories")
data class CategoryEntity(
    @PrimaryKey val id: Long,
    val name: String? = null,
    val parentId: Long? = null,
    val companyCode: Int = 0,
    val active: String? = "Y",
    val updatedAt: Long = 0L
)

@Entity(tableName = "items")
data class ItemEntity(
    @PrimaryKey val id: Long,
    val itemCode: String? = null,
    val barcode: String? = null,
    val name: String? = null,
    val categoryId: Long? = null,
    val unit: String? = null,
    val unitCost: Double = 0.0,
    val sellingPrice: Double = 0.0,
    val sellingPrice2: Double = 0.0,
    val sellingPrice3: Double = 0.0,
    val stockQty: Double = 0.0,
    val imageUrl: String? = null,
    val companyCode: Int = 0,
    val active: String? = "Y",
    val updatedAt: Long = 0L
)

@Entity(tableName = "customers")
data class CustomerEntity(
    @PrimaryKey val id: Long,
    val name: String? = null,
    val address: String? = null,
    val telephone: String? = null,
    val whatsapp: String? = null,
    val email: String? = null,
    val outstandingBalance: Double = 0.0,
    val companyCode: Int = 0,
    val active: String? = "Y",
    val updatedAt: Long = 0L
)

@Entity(tableName = "suppliers")
data class SupplierEntity(
    @PrimaryKey val id: Long,
    val name: String? = null,
    val address: String? = null,
    val telephone: String? = null,
    val email: String? = null,
    val outstandingBalance: Double = 0.0,
    val companyCode: Int = 0,
    val active: String? = "Y",
    val updatedAt: Long = 0L
)

@Entity(tableName = "sales_refs")
data class SalesRefEntity(
    @PrimaryKey val id: Long,
    val name: String? = null,
    val telephone: String? = null,
    val companyCode: Int = 0,
    val active: String? = "Y",
    val updatedAt: Long = 0L
)

@Entity(tableName = "invoices")
data class InvoiceEntity(
    @PrimaryKey val id: Long,
    val invoiceNo: String? = null,
    val invoiceDate: String? = null,
    val supplierId: Long = 0,
    val total: Double = 0.0,
    val paid: Double = 0.0,
    val companyCode: Int = 0,
    val isSynced: Boolean = true,
    val active: String? = "Y",
    val updatedAt: Long = 0L
)

@Entity(tableName = "stock_items")
data class StockItemEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val itemId: Long = 0,
    val invoiceId: Long? = null,
    val qty: Double = 0.0,
    val unitCost: Double = 0.0,
    val expiryDate: String? = null,
    val companyCode: Int = 0,
    val isSynced: Boolean = true,
    val updatedAt: Long = 0L
)

@Entity(tableName = "bills")
data class BillEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val billNo: Long = 0,
    val billingDate: String? = null,
    val billType: String = "CASH", // CASH | CREDIT | IMAGE
    val customerId: Long = 0,
    val cashCustomerName: String? = null,
    val salesRefId: Long = 0,
    val total: Double = 0.0,
    val discount: Double = 0.0,
    val discountValue: Double = 0.0,
    val cash: Double = 0.0,
    val cardPayment: Double = 0.0,
    val companyCode: Int = 0,
    val createdByUser: String? = null,
    val deviceName: String? = null,
    val isSynced: Boolean = false,
    val active: String? = "Y",
    val createdAt: Long = System.currentTimeMillis(),
    val updatedAt: Long = System.currentTimeMillis()
)

@Entity(tableName = "bill_lines")
data class BillLineEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val billLocalId: Long = 0,
    val itemId: Long = 0,
    val unitPrice: Double = 0.0,
    val qty: Double = 0.0,
    val returnQty: Double = 0.0,
    val discount: Double = 0.0,
    val discountValue: Double = 0.0,
    val freeIssueQty: Double = 0.0
)

@Entity(tableName = "customer_payments")
data class CustomerPaymentEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val customerId: Long = 0,
    val paymentDate: String? = null,
    val amount: Double = 0.0,
    val method: String? = null,
    val note: String? = null,
    val companyCode: Int = 0,
    val isSynced: Boolean = false,
    val createdAt: Long = System.currentTimeMillis()
)

// Owner → Customer refund payments (inverse direction of customer_payments).
// Created when an Image Bill's return amount exceeds its sale amount and the
// shop has to pay the customer back.
@Entity(tableName = "owner_customer_payments")
data class OwnerCustomerPaymentEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val customerId: Long = 0,
    val customerName: String? = null,
    val billId: Long = 0,
    val billType: String? = null,
    val paymentDate: String? = null,
    val amount: Double = 0.0,
    val method: String? = null,
    val note: String? = null,
    val companyCode: Int = 0,
    val isSynced: Boolean = false,
    val createdAt: Long = System.currentTimeMillis()
)

@Entity(tableName = "supplier_payments")
data class SupplierPaymentEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val supplierId: Long = 0,
    val paymentDate: String? = null,
    val amount: Double = 0.0,
    val method: String? = null,
    val note: String? = null,
    val companyCode: Int = 0,
    val isSynced: Boolean = false,
    val createdAt: Long = System.currentTimeMillis()
)

@Entity(tableName = "expenses")
data class ExpenseEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val expenseDate: String? = null,
    val category: String? = null,
    val amount: Double = 0.0,
    val note: String? = null,
    val companyCode: Int = 0,
    val isSynced: Boolean = false,
    val createdAt: Long = System.currentTimeMillis()
)

@Entity(tableName = "bill_templates")
data class BillTemplateEntity(
    @PrimaryKey val id: Long,
    val name: String? = null,
    val templateJson: String? = null,
    val companyCode: Int = 0,
    val updatedAt: Long = 0L
)

@Entity(tableName = "billing_configs")
data class BillingConfigEntity(
    @PrimaryKey val key: String,
    val value: String? = null,
    val companyCode: Int = 0,
    val updatedAt: Long = 0L
)

@Entity(tableName = "user_permissions")
data class UserPermissionEntity(
    @PrimaryKey val username: String,
    val permissionsJson: String? = null,
    val companyCode: Int = 0,
    val updatedAt: Long = 0L
)

@Entity(tableName = "ui_configs")
data class UiConfigEntity(
    @PrimaryKey val key: String,
    val value: String? = null,
    val companyCode: Int = 0,
    val updatedAt: Long = 0L
)

@Entity(tableName = "kitchen_orders")
data class KitchenOrderEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val serverId: Long? = null,
    val kotNo: String? = null,
    val kotDate: String? = null,
    val orderType: String? = "TAKEAWAY",
    val status: String? = "PENDING",
    val tableNo: String? = null,
    val subTotal: Double = 0.0,
    val serviceCharge: Double = 0.0,
    val grandTotal: Double = 0.0,
    val notes: String? = null,
    val companyCode: Int = 0,
    val isSynced: Boolean = false,
    val createdAt: Long = System.currentTimeMillis()
)
